// Ensure an actor is selected
let actor = canvas.tokens.controlled[0]?.actor;
if (!actor) {
    ui.notifications.warn("No actor selected!");
    return;
}

// Filter out the consumables with a max uses greater than 1
const consumables = actor.items.filter(item => item.type === 'consumable' && item.system.uses && item.system.uses.max > 1);

// Generate checkboxes for each consumable item
let checkboxes = consumables.map((item, index) => {
    return `<div style="margin-bottom: 10px"><input type="checkbox" id="checkbox-${index}" name="${item.name}"><label for="checkbox-${index}">${item.name} (${item.system.uses.value}/${item.system.uses.max} uses)</label></div>`;
}).join("");

// Function to reset selected items to max uses
async function resetSelectedItems(form) {
    for (let [key, value] of form.entries()) {
        if (value === 'on') {
            let item = consumables.find(item => item.name === key);
            await item.update({'system.uses.value': item.system.uses.max});
            console.log(`Reset uses for ${item.name} to maximum (${item.system.uses.max})`);
        }
    }
}

// Create and render the dialog. DialogV2 supplies the surrounding form.
await foundry.applications.api.DialogV2.wait({
    window: { title: "Reset Item Uses" },
    content: checkboxes,
    buttons: [
        {
            action: "reset",
            icon: "fas fa-redo",
            label: "Reset",
            default: true,
            callback: async (_event, button) => {
                await resetSelectedItems(new FormData(button.form));
            }
        }
    ],
    rejectClose: false
});
